const { api, action, params } = $input.first().json;

const apiConfigs = {
  hubspot: {
    base_url: 'https://api.hubapi.com/crm/v3',
    endpoints: {
      contacts: { method: 'GET', path: '/objects/contacts', query: { limit: params.limit || 100, properties: 'email,firstname,lastname,phone,company' } },
      companies: { method: 'GET', path: '/objects/companies', query: { limit: params.limit || 100, properties: 'name,domain,industry,numberofemployees' } },
      deals: { method: 'GET', path: '/objects/deals', query: { limit: params.limit || 100, properties: 'dealname,amount,dealstage,closedate,pipeline' } },
      leads: { method: 'GET', path: '/objects/contacts', query: { limit: params.limit || 100, properties: 'email,firstname,lastname,lifecyclestage', filterGroups: JSON.stringify([{ filters: [{ propertyName: 'lifecyclestage', operator: 'EQ', value: 'lead' }] }]) } },
      pipelines: { method: 'GET', path: '/pipelines/deals', query: {} },
      create_contact: { method: 'POST', path: '/objects/contacts', body: { properties: { email: params.email, firstname: params.firstname, lastname: params.lastname, phone: params.phone || '' } } },
      create_deal: { method: 'POST', path: '/objects/deals', body: { properties: { dealname: params.dealname, amount: params.amount, dealstage: params.stage || 'appointmentscheduled', pipeline: params.pipeline || 'default' } } },
      create_company: { method: 'POST', path: '/objects/companies', body: { properties: { name: params.name, domain: params.domain, industry: params.industry || '' } } }
    }
  },
  salesforce: {
    base_url: 'https://login.salesforce.com/services/data/v59.0',
    endpoints: {
      contacts: { method: 'GET', path: '/query', query: { q: params.query || 'SELECT Id, Name, Email, Phone, AccountId FROM Contact ORDER BY CreatedDate DESC LIMIT 100' } },
      companies: { method: 'GET', path: '/query', query: { q: params.query || 'SELECT Id, Name, Industry, NumberOfEmployees, Website FROM Account ORDER BY CreatedDate DESC LIMIT 100' } },
      deals: { method: 'GET', path: '/query', query: { q: params.query || `SELECT Id, Name, Amount, StageName, CloseDate FROM Opportunity ${params.stage ? "WHERE StageName = '" + params.stage + "'" : ''} ORDER BY CreatedDate DESC LIMIT 100` } },
      leads: { method: 'GET', path: '/query', query: { q: params.query || `SELECT Id, Name, Email, Company, Status FROM Lead ${params.status ? "WHERE Status = '" + params.status + "'" : ''} ORDER BY CreatedDate DESC LIMIT 100` } },
      pipelines: { method: 'GET', path: '/query', query: { q: 'SELECT Id, Name, StageName, Amount FROM Opportunity WHERE IsClosed = false ORDER BY StageName' } },
      create_contact: { method: 'POST', path: '/sobjects/Contact', body: { FirstName: params.firstname, LastName: params.lastname, Email: params.email, Phone: params.phone || '' } },
      create_lead: { method: 'POST', path: '/sobjects/Lead', body: { Company: params.company, FirstName: params.firstname, LastName: params.lastname, Email: params.email } },
      create_deal: { method: 'POST', path: '/sobjects/Opportunity', body: { Name: params.dealname, Amount: params.amount, StageName: params.stage || 'Prospecting', CloseDate: params.close_date || new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0] } }
    }
  },
  pipedrive: {
    base_url: 'https://api.pipedrive.com/v1',
    endpoints: {
      contacts: { method: 'GET', path: '/persons', query: { start: 0, limit: params.limit || 100, sort: 'add_time DESC' } },
      companies: { method: 'GET', path: '/organizations', query: { start: 0, limit: params.limit || 100, sort: 'add_time DESC' } },
      deals: { method: 'GET', path: '/deals', query: { start: 0, limit: params.limit || 100, status: params.status || 'open', sort: 'add_time DESC' } },
      leads: { method: 'GET', path: '/leads', query: { start: 0, limit: params.limit || 100 } },
      pipelines: { method: 'GET', path: '/pipelines', query: {} },
      create_contact: { method: 'POST', path: '/persons', body: { name: `${params.firstname || ''} ${params.lastname || ''}`.trim(), email: [{ value: params.email, primary: true }], phone: params.phone ? [{ value: params.phone, primary: true }] : [] } },
      create_deal: { method: 'POST', path: '/deals', body: { title: params.dealname, value: params.amount, currency: params.currency || 'USD', status: 'open' } },
      create_company: { method: 'POST', path: '/organizations', body: { name: params.name, address: params.address || '' } }
    }
  }
};

const config = apiConfigs[api];
if (!config) {
  return [{ json: { error: true, message: `Unknown CRM API: ${api}. Available: ${Object.keys(apiConfigs).join(', ')}` } }];
}

const endpoint = config.endpoints[action];
if (!endpoint) {
  return [{ json: { error: true, message: `Unknown action '${action}' for ${api}. Available: ${Object.keys(config.endpoints).join(', ')}` } }];
}

return [{
  json: {
    method: endpoint.method,
    url: config.base_url + endpoint.path,
    query: endpoint.query || {},
    body: endpoint.body || {},
    api: api,
    action: action
  }
}];

const input = $input.first().json;
const request = $('Build API Request').first().json;

if (input.error || input.statusCode >= 400) {
  return [{
    json: {
      error: true,
      api: request.api,
      action: request.action,
      status_code: input.statusCode || 500,
      message: input.message || input.error || 'API call failed',
      raw_error: input
    }
  }];
}

return [{
  json: {
    success: true,
    api: request.api,
    action: request.action,
    data: input.data || input.body || input,
    metadata: {
      timestamp: new Date().toISOString(),
      execution_id: $execution.id
    }
  }
}];
